class Solution {
public:
    vector<int> findProductsOfElements(vector<vector<long long>>& queries) {
        auto count_bit = [](long long n, int b) -> long long {
            long long period = 1LL << (b + 1);
            long long full = (n + 1) / period;
            long long rem = (n + 1) % period;
            return full * (1LL << b) + max(0LL, rem - (1LL << b));
        };

        auto total_bits = [&](long long n) -> long long {
            long long s = 0;
            for (int b = 0; b < 60; ++b) s += count_bit(n, b);
            return s;
        };

        auto total_power_sum = [&](long long n) -> long long {
            long long s = 0;
            for (int b = 0; b < 60; ++b) s += b * count_bit(n, b);
            return s;
        };

        auto sum_powers = [&](long long k) -> long long {
            if (k <= 0) return 0;
            long long low = 1, high = k, x = 0;
            while (low <= high) {
                long long mid = low + (high - low) / 2;
                if (total_bits(mid) <= k) {
                    x = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            long long res = total_power_sum(x);
            long long rem = k - total_bits(x);
            long long nxt = x + 1;
            for (int b = 0; b < 60; ++b) {
                if (rem == 0) break;
                if ((nxt >> b) & 1LL) {
                    res += b;
                    rem--;
                }
            }
            return res;
        };

        auto mod_pow = [](long long base, long long exp, long long mod) -> int {
            long long res = 1 % mod;
            base %= mod;
            while (exp > 0) {
                if (exp % 2 == 1) res = (res * base) % mod;
                base = (base * base) % mod;
                exp /= 2;
            }
            return res;
        };

        vector<int> ans;
        for (const auto& q : queries) {
            long long l = q[0], r = q[1], mod = q[2];
            long long exp = sum_powers(r + 1) - sum_powers(l);
            ans.push_back(mod_pow(2, exp, mod));
        }
        return ans;
    }
};

class Solution {
    public int[] findProductsOfElements(long[][] queries) {
        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            long l = queries[i][0], r = queries[i][1], mod = queries[i][2];
            long exp = sumPowers(r + 1) - sumPowers(l);
            ans[i] = modPow(2, exp, mod);
        }
        return ans;
    }

    private long countBit(long n, int b) {
        long period = 1L << (b + 1);
        long full = (n + 1) / period;
        long rem = (n + 1) % period;
        return full * (1L << b) + Math.max(0L, rem - (1L << b));
    }

    private long totalBits(long n) {
        long s = 0;
        for (int b = 0; b < 60; b++) s += countBit(n, b);
        return s;
    }

    private long totalPowerSum(long n) {
        long s = 0;
        for (int b = 0; b < 60; b++) s += b * countBit(n, b);
        return s;
    }

    private long sumPowers(long k) {
        if (k <= 0) return 0;
        long low = 1, high = k, x = 0;
        while (low <= high) {
            long mid = low + (high - low) / 2;
            if (totalBits(mid) <= k) {
                x = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        long res = totalPowerSum(x);
        long rem = k - totalBits(x);
        long nxt = x + 1;
        for (int b = 0; b < 60; b++) {
            if (rem == 0) break;
            if (((nxt >> b) & 1L) == 1L) {
                res += b;
                rem--;
            }
        }
        return res;
    }

    private int modPow(long base, long exp, long mod) {
        long res = 1 % mod;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return (int) res;
    }
}

var findProductsOfElements = function(queries) {
    function countBit(n, b) {
        const period = 1n << BigInt(b + 1);
        const full = (n + 1n) / period;
        const rem = (n + 1n) % period;
        const half = 1n << BigInt(b);
        return full * half + (rem > half ? rem - half : 0n);
    }

    function totalBits(n) {
        let s = 0n;
        for (let b = 0; b < 60; b++) s += countBit(n, b);
        return s;
    }

    function totalPowerSum(n) {
        let s = 0n;
        for (let b = 0; b < 60; b++) s += BigInt(b) * countBit(n, b);
        return s;
    }

    function sumPowers(k) {
        if (k <= 0n) return 0n;
        let low = 1n, high = k, x = 0n;
        while (low <= high) {
            const mid = (low + high) / 2n;
            if (totalBits(mid) <= k) {
                x = mid;
                low = mid + 1n;
            } else {
                high = mid - 1n;
            }
        }

        let res = totalPowerSum(x);
        let rem = k - totalBits(x);
        const nxt = x + 1n;
        for (let b = 0; b < 60; b++) {
            if (rem === 0n) break;
            if ((nxt >> BigInt(b)) & 1n) {
                res += BigInt(b);
                rem -= 1n;
            }
        }
        return res;
    }

    function modPow(base, exp, mod) {
        let res = 1n % mod;
        base = base % mod;
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2n;
        }
        return Number(res);
    }

    return queries.map(([l, r, mod]) => {
        const exp = sumPowers(BigInt(r + 1)) - sumPowers(BigInt(l));
        return modPow(2n, exp, BigInt(mod));
    });
};
